import functools
from typing import ForwardRef, Any, Callable
from fastapi.dependencies.utils import get_typed_signature
import inspect

# We'll use a helper to create a function in a separate "module" (via exec)
# to ensure different __globals__.

code = """
import functools

class MyModel:
    pass

def wrapped_func(x: 'MyModel'):
    return x

def wrap_it(f):
    @functools.wraps(f)
    def wrapper(x):
        return f(x)
    return wrapper

wrapped = wrap_it(wrapped_func)
"""

namespace = {}
exec(code, namespace)
wrapper = namespace['wrapped']

def test_wrapped_forward_ref():
    try:
        sig = get_typed_signature(wrapper)
        print("Successfully got signature")
        param = list(sig.parameters.values())[0]
        print(f"Annotation: {param.annotation}")
        # It should be resolved to MyModel
        # In the namespace, MyModel is namespace['MyModel']
        assert param.annotation is namespace['MyModel']
    except NameError as e:
        print(f"Caught expected NameError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_forward_ref()

